import{_ as e,o,c as r,a2 as n}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Respuestas instantáneas y atajos de palabra clave","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/instant-answers.md","filePath":"es-ES/user-guide/instant-answers.md","lastUpdated":1786117994000}'),s={name:"es-ES/user-guide/instant-answers.md"};function t(i,a,d,c,l,p){return o(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="respuestas-instantaneas-y-atajos-de-palabra-clave" tabindex="-1">Respuestas instantáneas y atajos de palabra clave <a class="header-anchor" href="#respuestas-instantaneas-y-atajos-de-palabra-clave" aria-label="Permalink to &quot;Respuestas instantáneas y atajos de palabra clave&quot;">​</a></h1><p>Algunos resultados aparecen al instante mientras escribes, sin esperar a una búsqueda de archivos — o bien siempre activos, o bien reservados detrás de una palabra clave corta que escribes antes de tu consulta real (para que una función grande como la búsqueda en el historial del navegador no compita por la atención en cada pulsación de tecla no relacionada). La mayoría de los que se activan por palabra clave tienen su palabra clave configurada en <strong>Configuración → Plugins → Configurar</strong>.</p><h2 id="siempre-activos" tabindex="-1">Siempre activos <a class="header-anchor" href="#siempre-activos" aria-label="Permalink to &quot;Siempre activos&quot;">​</a></h2><p>Estos no necesitan ninguna palabra clave — se activan en cuanto lo que escribes coincide con su patrón.</p><h3 id="calculadora" tabindex="-1">Calculadora <a class="header-anchor" href="#calculadora" aria-label="Permalink to &quot;Calculadora&quot;">​</a></h3><p>Escribe una expresión matemática directamente y el resultado aparece en vivo, con <strong>Intro</strong> copiándolo al portapapeles:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span></code></pre></div><p>También se admite la conversión explícita de base:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span></code></pre></div><h3 id="variables-de-entorno" tabindex="-1">Variables de entorno <a class="header-anchor" href="#variables-de-entorno" aria-label="Permalink to &quot;Variables de entorno&quot;">​</a></h3><ul><li><code>%NOMBRE%</code> expande una variable concreta (incluidas variables multirruta como <code>%PATH%</code>, dividida en una entrada por ruta).</li><li><code>%parcial</code> lista de forma difusa toda variable cuyo nombre coincida con <code>parcial</code>.</li></ul><h3 id="ejecutar-un-comando" tabindex="-1">Ejecutar un comando <a class="header-anchor" href="#ejecutar-un-comando" aria-label="Permalink to &quot;Ejecutar un comando&quot;">​</a></h3><ul><li><code>#&lt;comando&gt;</code> abre una ventana del símbolo del sistema y ejecuta <code>&lt;comando&gt;</code> <strong>como Administrador</strong>.</li><li><code>$&lt;comando&gt;</code> abre una ventana del símbolo del sistema y ejecuta <code>&lt;comando&gt;</code> con normalidad.</li></ul><h3 id="url-sueltas" tabindex="-1">URL sueltas <a class="header-anchor" href="#url-sueltas" aria-label="Permalink to &quot;URL sueltas&quot;">​</a></h3><p>Escribe o pega una dirección <code>http://</code>/<code>https://</code> y Lertaro te ofrece abrirla directamente.</p><h2 id="activados-por-palabra-clave-integrados-prefijo-configurable" tabindex="-1">Activados por palabra clave (integrados, prefijo configurable) <a class="header-anchor" href="#activados-por-palabra-clave-integrados-prefijo-configurable" aria-label="Permalink to &quot;Activados por palabra clave (integrados, prefijo configurable)&quot;">​</a></h2><p>Escribe la palabra clave, un espacio y luego tu consulta. Cada palabra clave usa por defecto un prefijo corto, pero se puede cambiar de forma independiente en el propio diálogo <strong>Configurar</strong> de ese plugin si coincide con algo que escribas a menudo.</p><table tabindex="0"><thead><tr><th>Palabra clave (por defecto)</th><th>Plugin</th><th>Qué busca</th></tr></thead><tbody><tr><td><code>ps</code></td><td>Gestor de procesos</td><td>Procesos en ejecución por nombre, PID o título de ventana (también coincidencias difusas/pinyin) — selecciona uno para eliminarlo.</td></tr><tr><td><code>win</code></td><td>Cambio de ventana</td><td>Las ventanas actualmente abiertas y activables — el mismo conjunto que muestra Alt+Tab — por título, nombre de proceso o PID. Selecciona una para traerla al primer plano.</td></tr><tr><td><code>bm</code></td><td>Datos del navegador</td><td>Marcadores e historial de los perfiles de navegador de la familia Chrome/Chromium y de la familia Firefox que hayas añadido en la propia configuración de ese plugin.</td></tr><tr><td><code>set</code></td><td>Core Extensions</td><td>Cada ajuste de la aplicación, con coincidencia difusa por nombre — elige uno para saltar directamente a él en Configuración, resaltado. Escribe <code>set</code> sin nada detrás para listar todos los ajustes.</td></tr></tbody></table><p>Cambio de ventana muestra por defecto una miniatura en vivo del contenido real de cada ventana como su icono, capturada en segundo plano para que nunca ralentice la escritura — un icono de aplicación normal aparece de inmediato, y la miniatura aparece gradualmente en cuanto está lista. Desactiva <strong>Mostrar contenido de la ventana como icono</strong> en <strong>Configuración → Plugins → Cambio de ventana → Configurar</strong> para omitir por completo esa captura y usar siempre el icono de la aplicación. Una ventana que se ejecute en pantalla completa exclusiva real (la mayoría de los juegos usan por defecto pantalla completa sin bordes, que esto gestiona bien) no se puede capturar de esta forma y siempre recurre a su icono de aplicación.</p><p>Datos del navegador indexa marcadores e historial de forma independiente — <strong>Indexar marcadores</strong> e <strong>Indexar historial</strong> son interruptores separados en <strong>Configuración → Plugins → Datos del navegador → Configurar</strong>, así que puedes desactivar el historial (suele crecer mucho más que los marcadores) y seguir buscando en los marcadores, o al revés.</p><h2 id="busqueda-web" tabindex="-1">Búsqueda web <a class="header-anchor" href="#busqueda-web" aria-label="Permalink to &quot;Búsqueda web&quot;">​</a></h2><p>Búsqueda web incluye palabras clave predeterminadas para varios motores/sitios — <code>bd</code> (Baidu), <code>g</code> (Google), <code>bing</code> (Bing), <code>gh</code> (GitHub), <code>wiki</code> (Wikipedia), <code>yt</code> (YouTube) — y te permite añadir, editar o eliminar entradas por completo, cada una con su propio nombre, palabra clave, icono y plantilla de URL, desde <strong>Configuración → Plugins → Búsqueda web → Configurar</strong>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g lertaro github</span></span></code></pre></div><p>abre una búsqueda de Google de &quot;lertaro github&quot; en tu navegador.</p><h2 id="traduccion" tabindex="-1">Traducción <a class="header-anchor" href="#traduccion" aria-label="Permalink to &quot;Traducción&quot;">​</a></h2><p>La palabra clave predeterminada del complemento de traducción es <code>tr</code>. Escribe texto después de ella para traducirlo al idioma seleccionado actualmente para la interfaz de Lertaro:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr hello</span></span></code></pre></div><p>El resultado aparece de forma asíncrona; pulsa <strong>Entrar</strong> o haz clic para copiarlo. El texto que se va a traducir se envía a Microsoft Translator, por lo que esta función requiere conexión a Internet. El idioma de destino es el idioma actual de la App. Puedes cambiar la palabra clave en <strong>Configuración → Plugins → Traducción → Configurar</strong>.</p><h2 id="filtros-de-archivos" tabindex="-1">Filtros de archivos <a class="header-anchor" href="#filtros-de-archivos" aria-label="Permalink to &quot;Filtros de archivos&quot;">​</a></h2><p>Indexa carpetas concretas bajo su propia regla, configurado por completo en <strong>Configuración → Plugins → Filtros de archivos → Configurar</strong>. Cada regla tiene su propia lista de <strong>Carpetas de destino</strong> (escaneadas recursivamente), un campo <strong>Extensiones / Patrón</strong> (por ejemplo, <code>*.exe;*.lnk</code> — se admiten varios patrones separados por <code>;</code> o <code>,</code>; el <code>*</code> por defecto coincide con cualquier archivo), y un <strong>Nombre de filtro</strong> opcional mostrado en la descripción del resultado. Las subcarpetas siempre se incluyen sin importar el patrón — solo los archivos se filtran por él.</p><p>Añade una <strong>Palabra clave de acceso directo</strong> para restringir las coincidencias de una regla detrás de un prefijo, igual que las palabras clave integradas de arriba, en lugar de mezclarlas siempre en el índice general.</p><h2 id="totalmente-personalizados-tu-defines-la-palabra-clave" tabindex="-1">Totalmente personalizados (tú defines la palabra clave) <a class="header-anchor" href="#totalmente-personalizados-tu-defines-la-palabra-clave" aria-label="Permalink to &quot;Totalmente personalizados (tú defines la palabra clave)&quot;">​</a></h2><h3 id="comandos-personalizados" tabindex="-1">Comandos personalizados <a class="header-anchor" href="#comandos-personalizados" aria-label="Permalink to &quot;Comandos personalizados&quot;">​</a></h3><p>Define tus propios comandos <code>&lt;palabra clave&gt; &lt;argumentos&gt;</code> que lancen un programa externo, configurados por completo en <strong>Configuración → Plugins → Comandos personalizados → Configurar</strong>. La plantilla de parámetros del comando admite marcadores posicionales (<code>%s1</code>, <code>%s2</code>, ... para cada argumento separado por espacios) y un marcador de &quot;todo el resto&quot; (<code>%s</code> para todo lo escrito después de la palabra clave).</p><p>Cada comando también tiene una casilla <strong>Mostrar en Navegación rápida</strong> (desactivada por defecto) — actívala para listar también ese comando como su propia entrada en la raíz del menú de <a href="./hotkeys.html#navegacion-rapida-raton">Navegación rápida</a>, pulsable sin necesidad de escribir su palabra clave en absoluto. El campo <strong>Submenú de Navegación rápida</strong> lo anida bajo un submenú con nombre en lugar de la raíz — usa <code>/</code> para anidar varios niveles de profundidad (por ejemplo, <code>Herramientas/Red</code> para un submenú de dos niveles); déjalo vacío para mantener el comando en el nivel superior. Un comando mostrado de esta forma se ejecuta con sus parámetros configurados tal cual, ya que aquí no hay texto de argumento escrito que sustituir en <code>%s1</code>/<code>%s</code>.</p><hr><p>Ninguno de los plugins de esta página es obligatorio — cada uno se puede deshabilitar de forma independiente en <a href="./settings/plugins.html">Configuración → Plugins</a> si no quieres que compita por espacio de teclado, y <a href="./search-syntax.html">Sintaxis de búsqueda</a> cubre el lenguaje de consulta difuso, separado y siempre activo, usado para todo lo demás (archivos, carpetas, aplicaciones).</p>`,37)])])}const g=e(s,[["render",t]]);export{m as __pageData,g as default};
